input.command:
set -eu; d=/root/shift-20261118; install -d -m700 "$d"; cp -p /etc/sudoers.d/larkspur /etc/nginx/sites-enabled/larkspur /usr/local/sbin/larkspur-orders "$d"/ 2>/dev/null || true; cp -p /etc/sudoers.d/larkspur "$d/sudoers.larkspur"; cp -p /etc/nginx/sites-enabled/larkspur "$d/nginx.larkspur"; cp -p /usr/local/sbin/larkspur-mailing-export "$d"/; usermod -L -e 1 jpark; gpasswd -d jpark sudo; sed -i '/NOPASSWD: \/usr\/bin\/rsync$/d' /etc/sudoers.d/larkspur; visudo -cf /etc/sudoers; python3 - <<'PY'
from pathlib import Path
p=Path('/usr/local/sbin/larkspur-orders');s=p.read_text();s=s[:s.index('eval "')] + s[s.index('rows=$(mysql'):].replace('mysql -h "$DBH" -u "$DBU"','mysql --defaults-extra-file=/etc/larkspur/report.cnf').replace('"$DBN" 2>&1','2>&1');p.write_text(s)
p=Path('/etc/nginx/sites-enabled/larkspur');s=p.read_text().replace('    location / {','''    location ~* /\\.(?!well-known(?:/|$)) { deny all; }
    location ~* (?:~|\\.(?:bak|backup|old|swp|ini|sql|env|conf|log))$ { deny all; }
    location ~* ^/wp-content/(?:uploads|cache)/.*\\.(?:php[0-9]*|phtml|phar)(?:[./]|$) { deny all; }
    location / {''').replace('location /assets-cache/', 'location ^~ /assets-cache/').replace('alias /var/www/larkspur-cache/;', 'alias /var/www/larkspur-cache/;\n        disable_symlinks on;\n        add_header X-Content-Type-Options nosniff;');p.write_text(s)
PY
nginx -t && service nginx reload; /usr/local/sbin/larkspur-orders; chmod -R g-w /var/www/larkspur; chgrp -R www-data /var/www/larkspur/wp-content/uploads; find /var/www/larkspur/wp-content/uploads -type d -exec chmod u+rwx {} +; chmod -R go-w /var/www/internal; note 'Locked unlisted jpark and removed its root privilege; deploy no longer gets unrestricted root rsync. Orders job now uses protected database client settings instead of executing site PHP as root. Blocked executable uploads and backup/dotfile downloads; removed group write on application code.'; tail -2 /var/log/larkspur-exports.log; ls -ld /var/www/larkspur/wp-content/{uploads,cache}

